import sys

def sum_by_mod(vec, d, r):
    # 把 vec 中下标同余于 r 的项相加
    s = 0
    for i in range(r, len(vec), d):
        s += vec[i]
    return s

def main():
    data = sys.stdin.read().strip().split()
    mstr = data[0]
    Q = int(data[1])
    ds = list(map(int, data[2:2+Q]))
    digits = [int(c) for c in mstr]
    n = len(digits)

    maxRem = max(0, n - 1)
    ways = [[None for _ in range(10)] for __ in range(maxRem + 1)]
    for L in range(maxRem + 1):
        for mn in range(10):
            ways[L][mn] = [0] * (9 * L + 1)
    for mn in range(10):
        ways[0][mn][0] = 1
    for L in range(1, maxRem + 1):
        for mn in range(10):
            cur = ways[L][mn]
            for x in range(mn, 10):
                prev = ways[L-1][x]
                # 卷积式转移：把 x 加到每个 sR
                for sR, cnt in enumerate(prev):
                    cur[x + sR] += cnt

    def solve_one(d):
        ans = 0
        # 位数小于 n
        for L in range(1, n):
            for f in range(1, 10):
                vec = ways[L-1][f]
                need = (-f) % d
                ans += sum_by_mod(vec, d, need)
        # 位数等于 n
        mn = 1
        Smod = 0
        ok = True
        for i, bound in enumerate(digits):
            for x in range(mn, bound):
                rem = n - i - 1
                vec = ways[rem][x]
                need = (-(Smod + x)) % d
                ans += sum_by_mod(vec, d, need)
            if bound < mn:
                ok = False
                break
            Smod = (Smod + bound) % d
            mn = bound
        if ok and Smod % d == 0:
            ans += 1
        return ans

    out = []
    for d in ds:
        out.append(str(solve_one(d)))
    print("\n".join(out))

if __name__ == "__main__":
    main()
