### Python

```python
import sys

def sum_by_mod(vec, d, r):
    """返回向量 vec 中下标模 d 余 r 的元素之和"""
    s = 0
    for i in range(r, len(vec), d):
        s += vec[i]
    return s

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    mstr = data[0]          # 上限 N 的字符串形式
    Q = int(data[1])
    queries = list(map(int, data[2:2+Q]))
    digits = [int(c) for c in mstr]
    n = len(digits)

    max_rem = max(0, n - 1)   # 最大剩余位数
    # ways[L][mn] 是一个长度为 9*L + 1 的列表
    ways = [[None] * 10 for _ in range(max_rem + 1)]
    for L in range(max_rem + 1):
        for mn in range(10):
            ways[L][mn] = [0] * (9 * L + 1)
    for mn in range(10):
        ways[0][mn][0] = 1

    for L in range(1, max_rem + 1):
        for mn in range(10):
            cur = ways[L][mn]
            for x in range(mn, 10):
                prev = ways[L-1][x]
                for sR, cnt in enumerate(prev):
                    cur[x + sR] += cnt

    def solve_one(k):
        ans = 0
        # 1. 位数小于 n 的平稳数
        for L in range(1, n):
            for f in range(1, 10):
                vec = ways[L-1][f]
                need = (-f) % k
                ans += sum_by_mod(vec, k, need)

        # 2. 位数等于 n 的平稳数
        mn = 1       # 第一位至少是 1
        Smod = 0     # 前缀和模 k
        ok = True
        for i, bound in enumerate(digits):
            for x in range(mn, bound):
                rem = n - i - 1
                vec = ways[rem][x]
                need = (-(Smod + x)) % k
                ans += sum_by_mod(vec, k, need)
            if bound < mn:
                ok = False
                break
            Smod = (Smod + bound) % k
            mn = bound

        if ok and Smod % k == 0:
            ans += 1
        return ans

    out = [str(solve_one(k)) for k in queries]
    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    main()
```

